#!/usr/bin/env python3
"""Compatibility entry point and final integration for the glossary edition."""
import argparse, importlib.util, re
from pathlib import Path
HERE=Path(__file__).resolve().parent
spec=importlib.util.spec_from_file_location('glossary_v2',HERE/'glossary_v2.py')
core=importlib.util.module_from_spec(spec);spec.loader.exec_module(core)
_original_revise=core.revise

def reviewed_revise(terms,sources):
    terms=_original_revise(terms,sources)
    advocacy={'label':'ASAN: For Whose Benefit? (includes Easy Read and Plain Language)','url':'https://autisticadvocacy.org/policy/briefs/intervention-ethics/','kind':'Autistic-led critique'}
    for term in terms:
        if term['term'] in ('ABA — Applied Behavior Analysis','Social validity','Neurodiversity-affirming practice'):
            term['sources'].append(dict(advocacy))
        if term['term']=='Gestalt language processing (GLP)':
            term['sources'].extend([
                {'label':'Lorang and colleagues: GLP/NLA—concerns and common ground','url':'https://pubs.asha.org/doi/10.1044/2025_PERSP-25-00055','kind':'Research-informed critique'},
                {'label':'Blanc and colleagues: the proposed NLA framework','url':'https://pubs.asha.org/doi/10.1044/2023_PERSP-23-00098','kind':'Proponents’ viewpoint; not proof of effectiveness'}])
        if term['term']=='Massachusetts N1 & N2 notices':
            term['sources'].append({'label':'Massachusetts DESE: Notice of School District Refusal to Act','url':'https://www.doe.mass.edu/specialeducation/iep/refusal-to-act/','kind':'Massachusetts official form'})
        if term['term'] in ('Supported decision-making','Autonomy & self-determination'):
            term['sources'].append({'label':'ASAN: self-determination and the right to make choices','url':'https://autisticadvocacy.org/self-determination/','kind':'Autistic-led rights guidance'})
    additions=[
        dict(term='Multilingual communication & AAC',cat='Communication',
             plain='Communication support that includes the languages a person uses with family and community.',
             detail='AAC assessment should consider the person’s languages, vocabulary, communication partners and cultural context. A system that works only in English may leave someone unable to participate with important people in their life.',
             why='A family should not have to choose between communication access and their home language.',
             look='A person uses one language with a grandparent and another at school. Their communication board or device needs useful vocabulary and partner support for both settings.',
             do='Tell the SLP which languages matter, who uses them and when. Ask about multilingual vocabulary, switching languages and trained interpretation for assessment or meetings.',
             ask='How will this communication system help me communicate with my family in the languages we actually use?',
             note='Knowing more than one language is not itself a communication disorder. A translated word list alone does not establish that a system is accessible or culturally appropriate.',
             sources=[{'label':'ASHA: Multilingual service delivery','url':'https://www.asha.org/practice-portal/professional-issues/multilingual-service-delivery/','kind':'Professional guidance'},{'label':'ASHA: Augmentative and alternative communication','url':'https://www.asha.org/practice-portal/professional-issues/augmentative-and-alternative-communication/','kind':'Clinical guidance'}],related=['AAC','Communication partner','Multimodal communication']),
        dict(term='Plain language & Easy Read',cat='Identity & support',
             plain='Two ways to make information easier to understand. They are related, but not identical.',
             detail='Plain language uses familiar words, clear organization and direct explanations. Easy Read typically adds shorter text, generous spacing and pictures that support each idea. A page is not necessarily Easy Read just because it has pictures or a larger-text button.',
             why='People need usable information to take part in decisions about their lives.',
             look='A service sends a long care document. The person asks for a short explanation, relevant pictures and time to discuss one decision at a time.',
             do='Ask what format the person prefers. Check understanding without turning the conversation into a test, and offer another explanation when needed.',
             ask='Can you explain the choices in a format I can understand and give me time to ask questions?',
             note='This glossary uses plain-language explanations; it is not a validated Easy Read edition. Pictures and simplified wording should support access without replacing important details.',
             sources=[{'label':'ASAN: Plain Language Resources','url':'https://autisticadvocacy.org/resources/','kind':'Autistic-led accessible resources'}],related=['Supported decision-making','Communication Bill of Rights']),
        dict(term='Self-advocacy & supported self-advocacy',cat='Rights & safety',
             plain='Expressing what matters to you and having help to do that when you need it.',
             detail='Self-advocacy can include speech, AAC, gestures, signs, choosing between options or clearly refusing. Supporters can help someone understand choices and communicate a view without substituting their own preference. Advocacy is not reserved for people who can speak, read or manage a meeting independently.',
             why='A caregiver’s knowledge matters, and the disabled person’s own preferences also need a reliable way into decisions.',
             look='Before a planning meeting, someone reviews accessible choices with a trusted supporter. During the meeting, the team addresses them directly and waits for their response.',
             do='Ask the person how they want to participate. Record what they expressed, what was observed and what a supporter is interpreting as separate information.',
             ask='What support would let me have more say in this decision?',
             note='An interpretation of behavior is not automatically a confirmed statement of the person’s wishes. Be transparent about uncertainty and keep offering accessible ways to agree, disagree or change course.',
             sources=[{'label':'ASAN: What we believe','url':'https://autisticadvocacy.org/about-asan/what-we-believe/','kind':'Autistic-led rights perspective'},{'label':'NJC: Communication Bill of Rights, third edition','url':'https://www.asha.org/njc/communication-bill-of-rights/','kind':'Communication rights guidance'}],related=['Assent','Autonomy & self-determination','Supported decision-making'])
    ]
    for item in additions:
        item['flag']=''
        terms.append(item)
    for term in terms:
        if term['term']=='Disability justice & intersectionality':
            term['do']='Ask whose access needs are being missed: people of color, LGBTQ+ people, multilingual families, people with intellectual disabilities and people with fewer financial resources. Offer concrete participation supports, and avoid asking one person to represent everyone.'
            term['sources'].append({'label':'ASAN: Civil rights are disability rights','url':'https://autisticadvocacy.org/about-asan/solidarity/','kind':'Autistic-led rights perspective'})

    autistic_sources={
        'asan':{'label':'ASAN: What we believe','url':'https://autisticadvocacy.org/about-asan/what-we-believe/','kind':'Autistic-led rights perspective'},
        'profound':{'label':'ASAN: The “profound autism” label hurts autistic people — Plain Language toolkit','url':'https://autisticadvocacy.org/the-profound-autism-label-hurts-autistic-people/','kind':'Autistic-led critique of the label'},
        'listen':{'label':'CommunicationFIRST: LISTEN — made by and with nonspeaking autistic people','url':'https://communicationfirst.org/listen/','kind':'Nonspeaking autistic perspectives'},
        'meetings':{'label':'CommunicationFIRST: Meeting tips by AAC users','url':'https://communicationfirst.org/best-practices-for-online-meetings/','kind':'AAC-user-authored access guidance'},
        'sartac':{'label':'SARTAC: Self-advocacy and the intellectual-disability rights movement','url':'https://selfadvocacyinfo.org/self-advocacy/','kind':'Self-advocacy resource'},
        'inclusion':{'label':'Listen Include Respect: Supporting self-advocacy','url':'https://www.listenincluderespect.com/supporting-self-advocacy','kind':'Inclusive participation guidance'},
        'actually':{'label':'Reframing Autism: Learn from #ActuallyAutistic voices','url':'https://reframingautism.org.au/service/i-am-an-ally/','kind':'Autistic-led community guidance'},
        'rights':{'label':'NJC: Communication Bill of Rights','url':'https://www.asha.org/njc/communication-bill-of-rights/','kind':'Communication rights guidance'}
    }
    new_rows=[
      ('Actually Autistic / #ActuallyAutistic','Identity & support','A phrase and hashtag used to foreground autistic people’s own experiences.',
       'It helps readers find accounts from autistic people rather than only commentary about them. Autistic people differ in communication, cognition, culture and support needs; one account cannot stand in for everyone.',
       'First-person perspectives can reveal barriers a supporter has not noticed.',
       'A family reads an autistic person’s explanation of sensory distress, then checks what helps their own family member.',
       'Seek a range of autistic perspectives, including nonspeaking contributors and people with intellectual disabilities. Keep the individual’s own needs central.',
       'Whose first-person experiences are missing from what we are reading?',
       'A hashtag is not a professional credential or proof that a claim is accurate. Nobody owes public disclosure or a personal story to deserve respect.',
       ['actually'],['Self-advocacy & supported self-advocacy','High support needs']),
      ('Autistic-led advocacy','Rights & safety','Advocacy in which autistic people help set the priorities and hold meaningful decision-making power.',
       'Consultation is useful, but leadership also concerns who decides, who is paid and whose disagreement can change the outcome. Families and professionals can contribute without replacing autistic leadership.',
       'A service can praise inclusion while making every decision without its users.',
       'A provider gives autistic advisers accessible proposals, preparation time and a real role in choosing changes.',
       'Ask how people with extensive support needs are included, what support is funded and what changed because of their input.',
       'Which decisions can autistic participants actually influence?',
       'This glossary is a family-publication resource informed by linked autistic-led work. It has not been reviewed or endorsed by those organizations, and it does not claim to speak for autistic people.',
       ['asan','inclusion'],['Nothing about us without us','Supported participation & accessible meetings']),
      ('Nothing about us without us','Rights & safety','People affected by a decision should have a meaningful part in making it.',
       'In autism advocacy, this means involving autistic people in decisions about autism. Extensive support needs call for better access and support, rather than automatic exclusion.',
       'Being discussed is different from being included.',
       'A planning team asks the person’s preferences before agreeing on a new daily routine.',
       'Offer accessible information and a way to respond before the decision is settled. Explain what changed after listening.',
       'How will my views affect this decision?',
       'Participation need not involve a public meeting, speech or agreeing with the group. A person can choose privacy or decline to participate.',
       ['asan'],['Autistic-led advocacy','Person-centered planning']),
      ('Interdependence','Adult life & services','People supporting one another, including when someone needs extensive or lifelong assistance.',
       'Autonomy concerns having a say in life; independence concerns doing things without assistance. Someone can need help with every personal-care task and still have preferences about how that help happens.',
       'Progress can include better support and greater choice without a reduction in care hours.',
       'A person needs hands-on dressing support and chooses the comfortable shirt, the helper or the order of the routine.',
       'Write goals for comfort, relationships, participation and influence alongside any skill goals. Keep essential assistance available.',
       'What would give me more choice while keeping the help I need?',
       'Needing support is not a failure. Family and paid supporters also need sustainable staffing, training, rest and backup.',
       ['asan','sartac'],['Autonomy & self-determination','High support needs','Quality of life']),
      ('Supported participation & accessible meetings','Rights & safety','Changing the format and providing assistance so someone can take part in a decision.',
       'Options include advance questions, pictures or objects, shorter sessions, quiet space, a trusted supporter, AAC and responses outside the meeting. Access should match the individual, rather than require everyone to use the same format.',
       'Fast conversation can exclude someone even when they are physically present.',
       'A team sends choices ahead of time and pauses while an AAC user finishes a message.',
       'Ask about access before the meeting. Address the person directly and record their contribution separately from a supporter’s interpretation.',
       'Can we change the format so I can take part?',
       'An AAC user’s account does not establish that every nonspeaking person has the same skills or support needs. Offer options and check what works.',
       ['meetings','inclusion'],['Processing time / latency','Self-advocacy & supported self-advocacy','Plain language & Easy Read']),
      ('Dissent / saying no','Rights & safety','Expressing disagreement, refusal or a wish to stop.',
       'Dissent may be expressed through speech, AAC, gesture or actions. A changed expression or movement is a reason to check what is happening, rather than assume either agreement or a specific meaning.',
       'A useful communication system must make disagreement possible.',
       'Someone pushes an activity away. A supporter pauses, checks discomfort and offers a break or another way to participate.',
       'Make stop, no, help and break available. Document how supporters respond and how uncertainty is checked.',
       'What happens when I say no?',
       'Essential care and immediate safety can involve difficult decisions. Use appropriate clinical guidance, explain what is happening and seek the least restrictive workable approach. Silence alone is not assent.',
       ['rights'],['Assent','Consent','Functional noncompliance / safe refusal'])
    ]
    for name,cat,plain,detail,why,look,action,ask,note,keys,related in new_rows:
        terms.append(dict(term=name,cat=cat,plain=plain,detail=detail,why=why,look=look,do=action,ask=ask,note=note,sources=[dict(autistic_sources[k]) for k in keys],related=related,flag=''))
    changes={
      'High support needs':('Name the actual help needed: communication access, personal care, health support, supervision and staffing. Also record choices, relationships and interests. Needing round-the-clock assistance does not remove someone’s right to influence daily life.',['asan','sartac']),
      'Profound autism':('Read the proposed research definition alongside autistic-led objections. Describe the person’s actual communication, intellectual disability, health and daily support needs rather than treating the label as a complete profile.',['profound']),
      'Presume competence':('Offer age-respectful communication and learning access without making someone prove worthiness first. Recognize genuine intellectual disability and teach at an accessible pace; dignity does not depend on hidden academic abilities.',['listen']),
      'Inclusion':('Check whether the person can choose, communicate, rest, form relationships and participate meaningfully. Fund the personal care, transport, sensory and staffing supports needed for access.',['inclusion']),
      'Stimming':('Protect harmless stimming and make regulation supports available. If an action causes injury, investigate pain, distress and safer options rather than making looking less autistic the objective.',['actually']),
      'Person-centered planning':('Ask what the person enjoys, avoids and wants to change using accessible options. Identify who will make their preferences happen, including when lifelong hands-on assistance is needed.',['inclusion']),
      'Social validity':('Review whose goals are being served. Include the autistic person’s comfort, refusal, preferences and relationships; a quieter or more compliant person is not automatically better supported.',['asan']),
      'Self-advocacy & supported self-advocacy':('Include everyday decisions as well as formal advocacy. Offer access to peers and self-advocacy groups with suitable support, without requiring a person to represent others or disclose private experiences.',['sartac','inclusion']),
      'Quality of life':('Review personally meaningful comfort, enjoyment, relationships and influence. Separate the person’s own report, observed patterns and supporter judgments; explain disagreements instead of collapsing them into one score.',['sartac'])
    }
    for term in terms:
        if term['term'] in changes:
            term['do'],keys=changes[term['term']]
            existing={source['url'] for source in term['sources']}
            term['sources'].extend(dict(autistic_sources[k]) for k in keys if autistic_sources[k]['url'] not in existing)
        if term['term']=='Profound autism':
            term['note']='Debated term. ASAN argues that the label can reinforce segregation and mistaken assumptions about people with intellectual and communication disabilities. Supporters argue that it makes persistent, intensive support needs visible. Disagreement about a label must not become a reason to withhold care, communication access or community inclusion.'

    expansion_sources={
      'aac':{'label':'ASHA: Augmentative and alternative communication','url':'https://www.asha.org/practice-portal/professional-issues/augmentative-and-alternative-communication/','kind':'Clinical guidance'},
      'passport':{'label':'PAMIS: A digital passport for people with profound and multiple learning disabilities','url':'https://pamis.org.uk/site/uploads/PAMIS-I-Can-If-You-Can-2023.pdf','kind':'Communication support resource'},
      'meet':{'label':'CommunicationFIRST: Meeting access tips by AAC users','url':'https://communicationfirst.org/best-practices-for-online-meetings/','kind':'AAC-user-authored guidance'},
      'lir':{'label':'Listen Include Respect: Guidelines for inclusive participation','url':'https://www.listenincluderespect.com/','kind':'Guidance developed with people with intellectual disabilities'},
      'written':{'label':'Listen Include Respect: Written information','url':'https://www.listenincluderespect.com/written-information','kind':'Accessible information guidance'},
      'peer':{'label':'SARTAC: Self-advocacy','url':'https://selfadvocacyinfo.org/self-advocacy/','kind':'Intellectual-disability self-advocacy resource'},
      'community':{'label':'ASAN: Community living','url':'https://autisticadvocacy.org/community-living/','kind':'Autistic-led rights perspective'},
      'work':{'label':'ASAN: Real Work for Real Pay','url':'https://autisticadvocacy.org/actioncenter/issues/employment/','kind':'Autistic-led employment advocacy'},
      'sdm':{'label':'SARTAC: My Voice Counts — supported decision-making guide','url':'https://selfadvocacyinfo.org/wp-content/uploads/2019/06/Support-decision-making-Guide-revised-2018.pdf','kind':'Self-advocacy guide'},
      'participation':{'label':'Listen Include Respect: Supporting self-advocacy','url':'https://www.listenincluderespect.com/supporting-self-advocacy','kind':'Self-advocacy participation guidance'},
      'sensory':{'label':'ASAN: About autism','url':'https://autisticadvocacy.org/about-asan/about-autism/','kind':'Autistic-led explanation'}
    }
    expansion_rows=[
      ('Communication passport','Communication','A short, personal guide to how someone communicates and how to communicate with them.','It can include preferred methods, yes/no or refusal signals, processing time and practical access needs. It is a starting point for getting to know the person, not a substitute for interacting with them.','A new supporter needs to understand a person’s signals without repeated guessing.','The passport explains that reaching toward an object may be a choice, while turning away is a reason to pause and check.','Create it with the person as far as possible; label supporter interpretations, date updates and share only what is needed.','What would a new person need to know to understand me?','Protect privacy. A passport is not a medical order or proof that every observed action has one fixed meaning.','passport','Care handoff;Multimodal communication','document,person,speech'),
      ('AAC partner training','Communication','Helping the people around an AAC user become better communication partners.','Training may cover access, modeling, waiting, responding and handling breakdowns. Giving someone a device without helping partners use it can leave communication difficult.','Communication depends on what partners do as well as the tool.','A supporter learns to pause for a response rather than repeat the question immediately.','Ask the SLP for practice in everyday routines, including with substitute staff.','What do my communication partners need to learn?','Partner training should increase the person’s control of messages, not coach them toward a preferred answer.','aac','Communication partner;Processing time / latency','device,people,book'),
      ('AAC personalization','Communication','Making a communication system fit the person’s own life and interests.','Useful vocabulary includes people, places, opinions, questions, humor, refusal and personally important activities. Personalization also concerns the way the person selects messages.','A system limited to adult-selected requests can restrict what someone gets to say.','A teen has words for favorite films, a friend’s name, “that is funny” and “I disagree.”','Review missing words with the person and keep a way to request new vocabulary.','What do I want to say that is missing here?','Do not remove important words as a reward or consequence. An accessible layout may need specialist review before major changes.','aac','Robust AAC;Core & fringe vocabulary','device,heart,letters'),
      ('AAC access barriers','Communication','Things that prevent someone from using their communication system when they need it.','Examples include an uncharged device, unsuitable mounting, unavailable symbols, an inaccessible touch target or partners who do not wait. A barrier is a problem to investigate rather than proof that the person cannot communicate.','Access can fail even when a tool is technically available.','The device is nearby but out of reach during personal care.','Check availability, physical access and partner responses across the day; arrange a workable backup.','Can I actually reach and use my communication right now?','Changing use can also reflect preference, fatigue or health. Assess the circumstances rather than assuming one explanation.','aac','Access method;Low-tech AAC backup','device,shield,magnify'),
      ('Cognitive accessibility','Identity & support','Making information and activities easier to understand, remember and navigate.','Supports can include familiar language, pictures or objects, one idea at a time, a predictable sequence and help reviewing choices. Different people need different formats.','A person may be excluded by the way a choice is presented.','A provider explains two options with concrete examples instead of reading a long form aloud.','Ask which format helps and offer time to return to the information.','Can you show me what each option would mean in my day?','Simple information should remain accurate and age-respectful. Check understanding without making the person perform for an audience.','written','Plain language & Easy Read;Supported participation & accessible meetings','book,steps,person'),
      ('Visual schedule','Sensory & regulation','A way to show what is happening using pictures, objects, words or another accessible format.','It can show a whole day or a short activity sequence. Its usefulness depends on whether the person understands the symbols and whether the schedule reflects what actually happens.','Knowing what comes next may make a transition easier to understand.','A familiar object signals a trip to the pool; a picture shows that home follows afterward.','Start with a small, meaningful sequence and include a way to show changes.','How will I know what is happening next?','A schedule should provide information, not promise an event that cannot happen or remove someone’s ability to object.','sensory','Objects & tactile symbols;Transition services','calendar,grid,arrow'),
      ('Sensory accommodations','Sensory & regulation','Changes that make a sensory environment more workable for a person.','Options can involve sound, lighting, touch, clothing, movement, seating or breaks. Ask what helps this person rather than assuming one standard autism-friendly setup.','Participation may improve when the environment becomes more comfortable.','Someone chooses a quieter table and keeps their headphones available.','Notice preferences and offer a manageable adjustment before increasing demands.','What can we change in this space to help me feel comfortable?','Accommodation is not a reason to ignore new pain or illness. Do not force sensory experiences to make someone appear more tolerant.','sensory','Sensory processing;Sensory overload','headphones,home,shield'),
      ('Genuine choice','Rights & safety','A choice with understandable, available options and a response that matters.','The person needs a usable way to select, refuse or ask for something else. Two options do not create meaningful choice if one is unavailable or the answer will be ignored.','Choice can become a performance when adults have already decided the outcome.','A supporter offers two available shirts and accepts the person’s selection.','Make the options concrete, explain limits honestly and check that refusal is possible.','Will my answer change what happens?','Some decisions have real safety or practical limits. Explain those limits and preserve the choices that remain.','sdm','Dissent / saying no;Autonomy & self-determination','fork,person,checklist'),
      ('Proxy reporting','Identity & support','Someone reporting their observations or judgments about another person’s experience.','A family member or supporter may offer valuable information when direct reporting is difficult. Their account still needs to be distinguished from the person’s own communication.','A supporter’s interpretation can accidentally become recorded as a confirmed preference.','A report says “staff observed that the person returned to the activity,” rather than “the person said they loved it.”','Label who supplied each observation and keep looking for accessible ways to check the person’s view.','Is this what I communicated, or what somebody thinks I meant?','Disagreement between observers deserves investigation. Neither familiarity nor a professional title makes an interpretation certain.','participation','Quality of life;Yes/no reliability','document,people,magnify'),
      ('Supported decision-making agreement','Adult life & services','A record of who helps someone understand and make decisions, and what help they want.','It may describe areas of support, communication arrangements and boundaries. The purpose is to support the person’s decisions rather than simply transfer choices to the supporter.','Clear roles can reduce confusion and unwanted control.','Someone identifies a trusted person to help compare service options and explain paperwork.','Ask how the person can choose supporters, express disagreement and review the arrangement.','Who do I want helping me with this decision, and how?','Legal recognition and formal requirements differ by location. Get appropriate local advice for legal documents; a glossary does not establish decision-making authority.','sdm','Supported decision-making;Guardianship','document,support,lock'),
      ('Peer support','Rights & safety','Support from people who share relevant lived experience.','It can include practical ideas, connection and learning about rights. Shared experience does not mean identical needs, and someone may need communication or other assistance to join in.','Meeting peers can reduce the feeling of being the only person facing a barrier.','An AAC user exchanges ideas with other AAC users about meeting access.','Ask about accessible formats, support-person arrangements and whether the person wants to participate.','Can I connect with people who understand something about my experience?','Participation is optional. Do not pressure someone to share private details or assume peer advice replaces individual clinical guidance.','peer','Self-advocacy & supported self-advocacy;Community participation','people,heart,dialogue'),
      ('Self-advocacy group','Rights & safety','A group where disabled people work together on their own priorities and rights.','Groups may share experiences, learn about decisions and take collective action. People with intellectual disabilities have a long self-advocacy history; speaking fluently is not a prerequisite for belonging.','Advocacy can grow through relationships and practice.','Members discuss what makes their local transport difficult to use and choose an issue to raise.','Ask who sets the agenda, what access is offered and how people with substantial support needs can participate.','What do members want to change?','A social activity can be valuable without being self-advocacy. Look for real influence by the people the group represents.','peer','Autistic-led advocacy;Supported participation & accessible meetings','people,checklist,community'),
      ('Co-production','Rights & safety','People affected by a service sharing meaningful influence in designing or improving it.','It involves participation before decisions are fixed, rather than only giving feedback afterward. The term can be used loosely, so ask what authority participants actually have.','A consultation may collect stories without changing a service.','Service users help select the access features of a new program and review whether they work.','Agree on accessible information, support, decision roles and how contributions will be recognized.','What can we change together before this is finalized?','Calling a process co-production does not establish equal power. Be clear about limits and show how input changed the result.','lir','Autistic-led advocacy;Nothing about us without us','people,hand,document'),
      ('Tokenism','Rights & safety','Including someone mainly to create the appearance of representation while giving them little influence.','A person can be invited or photographed yet excluded from meaningful decisions. Representation also needs access, preparation and room to disagree.','An invitation alone does not establish inclusion.','An organization asks a disabled adviser to attend but sends inaccessible materials and ignores their feedback.','Ask what decisions participants can influence and what changed after their involvement.','Am I here to help shape the decision, or only to be seen?','One person cannot represent every autistic person or every level of support need. Seek a range of perspectives without making disclosure a condition of respect.','participation','Autistic-led advocacy;Supported participation & accessible meetings','person,document,question'),
      ('Circle of support','Adult life & services','People who work with a person to help sustain the life and relationships they want.','A circle may include family, friends, trusted supporters and professionals, with roles suited to the person’s preferences. It should expand useful support rather than become a group that automatically decides everything for them.','Care can become fragile when one person holds every responsibility.','Different trusted people help with communication, outings and planning, while checking what the person wants.','Name roles and review who the person is comfortable involving.','Who do I want around me, and what help would I welcome?','A circle is not automatically a legal decision-making body. Share personal information carefully and distinguish informal help from formal responsibilities.','sdm','Interdependence;Person-centered planning','support,home,people'),
      ('Continuity of support','Daily care & health','Keeping essential knowledge and practical support available when staff or circumstances change.','Continuity can involve familiar routines, accessible handovers, training and clear responsibility. It should preserve useful knowledge while allowing preferences and needs to change.','Repeatedly starting from scratch can make access and communication harder.','A substitute knows the person’s communication methods and where to find current care instructions.','Keep the key handover current and check that incoming supporters can use it.','What must the next supporter know before taking over?','A written note does not replace training, clinical orders or a competent handover when those are required.','community','Care handoff;Direct support professional (DSP)','handed,calendar,support'),
      ('Backup support plan','Adult life & services','A practical plan for what happens when usual support is unavailable.','It identifies essential tasks, who to contact, what alternatives are actually available and where current instructions are kept. A name on a list is not the same as confirmed coverage.','People with extensive support needs may not be able to absorb a missed shift without help.','The plan identifies who coordinates a replacement and how the family is notified.','Check contact details, agreed roles and realistic alternatives before a disruption occurs.','Who does what if today’s support does not arrive?','Emergency medical instructions belong in current clinical plans. Do not assume an untrained substitute can provide specialized care.','community','Care handoff;Respite;Safety plan','calendar,shield,handed'),
      ('Supported employment','Adult life & services','Individualized assistance that helps a disabled person pursue and keep paid work.','Support can include finding a suitable role, learning tasks, communication access, workplace adjustments and ongoing assistance. A useful plan starts with the person’s preferences rather than a placement target.','Work goals need to connect to a job the person wants and support that is available.','A worker has help learning a task and an accessible way to request clarification or a break.','Ask how interests, pay, access and continuing support will be addressed.','What work would I like to explore, and what help would make it possible?','Employment is one possible part of a good life, not a measure of someone’s worth. Eligibility and program arrangements vary.','work','Transition services;Quality of life','hand,person,support'),
      ('Relationship support','Adult life & services','Help that makes it easier to form and maintain relationships the person values.','This may involve communication access, transport, time together, privacy and support to understand boundaries. Relationships should not be reduced to a count of supervised group activities.','A person can be surrounded by staff and still lack chosen companionship.','A supporter helps arrange a regular visit with a friend and makes space for their interaction.','Ask who matters to the person and which practical barriers get in the way.','Who would I like to spend time with?','Respect consent, privacy and the other person’s boundaries. Support needs do not erase a person’s right to meaningful connection.','community','Community participation;Body privacy & personal care','heart,people,home'),
      ('Community belonging','Adult life & services','Being recognized, welcomed and connected in places and relationships that matter to you.','Being physically present is only one part. Belonging also concerns familiarity, choice, access and opportunities to contribute without having to hide harmless autistic traits.','An outing can happen without meaningful participation or connection.','A familiar local venue learns a person’s communication needs and welcomes their regular visits.','Notice which places the person chooses and what support makes returning enjoyable.','Where do I feel welcome, and where would I like to return?','Community inclusion needs resources and practical assistance. It should not be used to withdraw intensive support.','community','Inclusion;Community participation','community,heart,person')
    ]
    for name,cat,plain,detail,why,look,action,ask,note,key,related,icon in expansion_rows:
        terms.append(dict(term=name,cat=cat,plain=plain,detail=detail,why=why,look=look,do=action,ask=ask,note=note,sources=[dict(expansion_sources[key])],related=related.split(';'),flag=''))
        _expansion_icons[name]=icon
    return terms
core.revise=reviewed_revise
_expansion_icons={}
_base_icon=core.art.spec_for
_voice_icons={'Actually Autistic / #ActuallyAutistic':'person,dialogue,book','Autistic-led advocacy':'people,speech,checklist','Nothing about us without us':'people,document,support','Interdependence':'home,people,linked','Supported participation & accessible meetings':'calendar,device,people','Dissent / saying no':'speech,pause,person'}
core.art.spec_for=lambda term: _expansion_icons.get(term['term']) or (_voice_icons[term['term']] if term['term'] in _voice_icons else _base_icon(term))

CSS='''/* Final glossary integration: native no-JS reading and unobscured headings. */
.cg-root:not(.cg-enhanced) .cg-workspace{display:block}
.cg-root:not(.cg-enhanced) .cg-start nav{display:none!important}
.cg-tools>summary{display:flex;align-items:center;justify-content:center;gap:8px;white-space:nowrap}
.cg-tools>summary::after{display:inline!important;position:static!important;font-size:12px;margin:0!important}
.cg-term{scroll-margin-top:calc(var(--cg-toolbar-height,180px) + 18px)}
.cg-sidebar{top:calc(var(--cg-toolbar-height,160px) + 20px)}
.cg-mobile-start{display:none}
@media(max-width:760px){
.cg-root .cg-start{display:none}
.cg-root .cg-mobile-start{display:block;margin-top:18px;border:1px solid var(--cg-line);border-radius:12px;background:var(--cg-soft);padding:0 15px;font-size:14px}
.cg-mobile-start>summary{min-height:48px;padding:12px 0;font-weight:700}
.cg-mobile-start nav{display:grid;gap:4px;padding-bottom:12px}
.cg-mobile-start nav button{display:flex;justify-content:space-between;gap:10px;background:transparent;border:0;border-top:1px solid var(--cg-line);font-size:14px;border-radius:0;padding:11px 0}
.cg-root .cg-reading-row #cg-compare{display:none}
.cg-tools>summary{min-height:44px;font-size:13px}
.cg-tools>div{top:51px}
.cg-term{scroll-margin-top:calc(var(--cg-toolbar-height,205px) + 18px)}
}
@media print{.cg-mobile-start{display:none!important}}
'''
JS='''/* Final glossary toolbar measurements and compact mobile menu. */
(()=>{const root=document.querySelector('.cg-v2.cg-enhanced');if(!root)return;
const toolbar=root.querySelector('#cg-search-tools');
const measure=()=>{if(toolbar)root.style.setProperty('--cg-toolbar-height',Math.ceil(toolbar.getBoundingClientRect().height)+'px');};
measure();if(typeof ResizeObserver==='function')new ResizeObserver(measure).observe(toolbar);else window.addEventListener('resize',measure);
root.querySelectorAll('[data-tool="compare"]').forEach(button=>button.addEventListener('click',()=>root.querySelector('#cg-compare').click()));
})();
'''

def build(root):
    root=Path(root);core.build(root)
    page=root/'caregiver-glossary.html'
    if not page.exists():return
    text=page.read_text()
    text=text.replace('<button data-tool="questions">Print my saved questions</button>','<button data-tool="questions">Print my saved questions</button><button data-tool="compare">Often mixed-up terms</button>',1)
    aside=re.search(r'<aside class="cg-start">(.*?)</aside>',text,re.S)
    if aside:
        nav=re.search(r'<nav[^>]*data-js>(.*?)</nav>',aside[1],re.S)
        if nav:
            mobile='<details class="cg-mobile-start" data-js><summary>Not sure? Browse by situation</summary><nav aria-label="Situations on a small screen">'+nav[1]+'</nav></details>'
            marker='<p class="cg-reassure">You do not need to learn every word. Find the one you need today.</p>'
            text=text.replace(marker,marker+mobile,1)
    text=text.replace('<section class="cg-closing">', '<section class="cg-closing" id="autistic-self-advocacy" aria-labelledby="autistic-self-advocacy-title"><div><p class="cg-eyebrow">Autistic perspectives · meaningful participation</p><h2 id="autistic-self-advocacy-title">A say in your own life.</h2></div><div><p>Needing extensive or lifelong help does not make someone less entitled to communication, belonging, privacy or choice. Self-advocacy can happen in small everyday decisions and with substantial support.</p><p>Begin with the person: offer accessible choices; make no, stop and help usable; allow processing time; and distinguish what they communicated from what someone else interpreted. When preferences are unclear, keep checking. Do not invent a first-person account on their behalf.</p><p>Autistic people with intellectual disabilities and nonspeaking autistic people belong in autism advocacy. Families bring important knowledge, while the person’s own experience deserves a direct route into decisions. No single advocate represents everybody, and no one needs to be a public advocate to deserve rights.</p><p>Start with <a href="#term-self-advocacy-supported-self-advocacy">supported self-advocacy</a>, <a href="#term-dissent-saying-no">saying no</a>, <a href="#term-supported-participation-accessible-meetings">accessible meetings</a> and <a href="#term-interdependence">interdependence</a>.</p><p><a href="https://communicationfirst.org/listen/">LISTEN: a film made by and with nonspeaking autistic people</a> offers first-person perspectives. Its full version addresses restraint; shorter and audio-described options and transcripts are available. <a href="https://selfadvocacyinfo.org/self-advocacy/">SARTAC introduces the intellectual-disability self-advocacy movement</a>. <a href="https://autisticadvocacy.org/the-profound-autism-label-hurts-autistic-people/">ASAN’s Plain Language toolkit explains its objections to “profound autism”</a>; the glossary also explains why some researchers and families use the term.</p><p>This is an editorial guide informed by these resources, not an autistic-authored testimony or a claim of endorsement. Listening to autistic people includes listening when their perspectives challenge our assumptions.</p></div></section>'+'<section class="cg-closing">',1)
    text=text.replace('<p class="cg-reassure">', '<p><a href="#autistic-self-advocacy">Autistic perspectives and self-advocacy with extensive support needs ↗</a></p><p class="cg-reassure">',1)
    text=text.replace('Updated October 20, 2026.', 'Updated October 21, 2026.')
    text=text.replace('We use autistic person by default and respect individual preference.', 'This guide welcomes disabled readers, family members, paid supporters and professionals. We use autistic person by default and respect individual preference. Language, race, income, gender and family structure can affect access; nobody should have to use the perfect vocabulary to ask for help.')
    text=text.replace('20261020-expanded-v2','20261021-inclusive-v3')

    # A compact visual entrance and optional secondary controls.
    text=text.replace('A little clarity.<br>A lot more understanding.', 'Understand the word.<br>Find your next step.')
    text=text.replace('The caregiver’s glossary to high-support and profound autism.', 'A plain-English guide to autism, communication, support and everyday rights.')
    text=text.replace('What word or situation are you looking for?', 'Find a word or a situation')
    text=text.replace('Try AAC, body signals, school says no…', 'Try “AAC”, “saying no” or “school says no”…')
    text=re.sub(r'<aside class="cg-start">.*?</aside>', '', text, flags=re.S)
    text=re.sub(r'<details class="cg-mobile-start".*?</details>', '', text, flags=re.S)
    text=re.sub(r'<aside class="cg-sidebar".*?</aside>', '', text, flags=re.S)
    text=re.sub(r'(<nav class="cg-alphabet".*?</nav>)', r'<details class="cg-letter-menu" data-js><summary>Browse A–Z</summary>\1</details>', text, flags=re.S)
    topics=[('communication','Communication','AAC, speech & being understood','care-clipboard'),('school','School & IEPs','Meetings, services & useful questions','journal-v2'),('distress','When things feel harder','Sensory needs, distress & health','yankee-toolbox'),('adult','Care & adult life','Daily support, choices & planning','home')]
    tiles=''.join('<button type="button" data-route="'+key+'"><img src="/assets/navigation-watercolors/'+image+'-320.webp" width="100" height="100" alt=""><span><b>'+title+'</b><small>'+description+'</small></span><span class="cg-tile-arrow" aria-hidden="true">↗</span></button>' for key,title,description,image in topics)
    entrance='<section class="cg-visual-topics cg-wrap" aria-labelledby="cg-visual-title" data-js><div class="cg-visual-heading"><h2 id="cg-visual-title">Start with what you need.</h2><span>Choose a path, or search below.</span></div><nav aria-label="Choose a glossary starting point">'+tiles+'</nav><p class="cg-visual-note"><a href="#autistic-self-advocacy">Autistic perspectives & supported self-advocacy ↗</a><span>201 terms · no account needed</span></p></section>'
    text=text.replace('<section class="cg-search-tools"',entrance+'<section class="cg-search-tools"',1)
    text=re.sub(r'<p><a href="#autistic-self-advocacy">Autistic perspectives and self-advocacy with extensive support needs ↗</a></p>','',text)
    text=text.replace('You do not need to learn every word. Find the one you need today.','One clear definition. An everyday example. A question you can use.')
    text=re.sub(r'<section class="cg-sources"><h3>Read further</h3>(.*?)</section>',r'<details class="cg-sources"><summary>Sources & further reading</summary>\1</details>',text,flags=re.S)
    text=text.replace('Quick read','Essentials').replace('Full explanations','More detail')
    text=text.replace('20261021-inclusive-v3','20261021-visual-v4')
    text=text.replace('201 terms',str(text.count('<details class="cg-term"'))+' terms')

    # One primary search, optional controls and a small starting selection.
    text=text.replace('Understand the word.<br>Find your next step.','A little clarity.')
    text=text.replace('A plain-English guide to autism, communication, support and everyday rights.', 'Autism, communication and everyday support. Explained clearly.')
    text=text.replace(', explained without making you learn a second language.', '. Find one useful answer, then take the next step.')
    text=text.replace('<p class="cg-reassure">One clear definition. An everyday example. A question you can use.</p>','')
    search=re.search(r'<section class="cg-search-tools".*?</section>',text,re.S)
    if search:
        original=search[0]
        field=re.search(r'<div class="cg-search-field">.*?</div></div>',original,re.S)[0]
        topic=re.search(r'<div class="cg-topic-select">.*?</div>',original,re.S)[0]
        tools=re.search(r'<details class="cg-tools">.*?</details>',original,re.S)[0]
        reading=original[original.index('<div class="cg-reading-row">'):].removesuffix('</div></section>')
        examples='<div class="cg-example-searches"><span>Try</span><button type="button" data-example="AAC">AAC</button><button type="button" data-example="IEP">IEP</button><button type="button" data-example="saying no">Saying no</button><button type="button" data-example="body signals">Body signals</button><button type="button" data-tool="reset" class="cg-browse-all">Browse all terms ↗</button></div>'
        simplified='<section class="cg-search-tools cg-primary-search" id="cg-search-tools" aria-label="Find a term" data-js><div class="cg-wrap">'+field+examples+'<details class="cg-options"><summary>Filters & reading options</summary><div class="cg-option-panel">'+topic+tools+reading+'</div></details></div></section>'
        text=text.replace(original,'',1)
        text=text.replace('<section class="cg-visual-topics',simplified+'<section class="cg-visual-topics',1)
    text=text.replace('Choose a path, or search below.','A few good places to begin.')
    extras='<button type="button" data-route="rights" aria-pressed="false"><img src="/assets/library-watercolors/advocacy-320.webp" width="100" height="100" alt=""><span><b>Choice & rights</b><small>Self-advocacy, refusal & being heard</small></span><span class="cg-tile-arrow" aria-hidden="true">↗</span></button><button type="button" data-route="identity" aria-pressed="false"><img src="/assets/navigation-watercolors/search-320.webp" width="100" height="100" alt=""><span><b>Understanding autism</b><small>Identity, differences & support needs</small></span><span class="cg-tile-arrow" aria-hidden="true">↗</span></button>'
    text=re.sub(r'(<nav aria-label="Choose a glossary starting point">.*?)(</nav>)',lambda match:match[1]+extras+match[2],text,count=1,flags=re.S)
    text=text.replace('Clear this view','Browse all terms')
    text=text.replace('20261021-visual-v4','20261021-refined-v5')
    page.write_text(text,encoding='utf-8')
    for path,addition,marker in [(root/'assets/caregiver-glossary.css',CSS,'/* Final glossary integration:'),(root/'assets/caregiver-glossary.js',JS,'/* Final glossary toolbar measurements')]:
        source=path.read_text()
        if marker not in source:path.write_text(source+'\n'+addition,encoding='utf-8')

    css_path=root/'assets/caregiver-glossary.css'
    css_path.write_text(css_path.read_text().split('/* Visual glossary entrance v4 */')[0]+VISUAL_CSS)
    js_path=root/'assets/caregiver-glossary.js'
    js=js_path.read_text().replace('limit:24','limit:12').replace('state.limit=24','state.limit=12').replace('state.limit+=24','state.limit+=12')
    js=js.replace("select.value=state.topic;$$('[data-route]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.route===state.route)));",'select.value=state.topic;')
    js=js.replace('select.value=state.topic;', "select.value=state.topic;$$('[data-route]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.route===state.route)));")
    js=js.replace("communication:['Speech vs.'", "communication:['Communication passport','AAC partner training','AAC personalization','AAC access barriers','Speech vs.'")
    js=js.replace("adult:['Person-centered'", "adult:['Circle of support','Continuity of support','Backup support plan','Supported employment','Relationship support','Community belonging','Person-centered'")

    if '/* Refined glossary interaction v5 */' not in js:
        js=js.replace("const state={topic:'All',letter:'',route:'',", "const state={topic:'All',letter:'',route:'start',")
        js=js.replace("const routeNames={school:", "routes.start=['AAC —','Assent','Interoception','IEP —','High support needs','Self-advocacy &'];routes.rights=['Self-advocacy &','Dissent /','Genuine choice','Autistic-led','Supported participation','Nothing about','Consent','Assent','Disability justice','Communication Bill'];routes.identity=['Autism /','Actually Autistic','High support needs','Level 3','Intellectual disability','Profound autism','Neurodiversity /','Identity-first'];const routeNames={start:'Six useful starting points',rights:'Choice, rights and self-advocacy',identity:'Understanding autism and support needs',school:")
        js=js.replace("root.classList.add('cg-enhanced');", "/* Refined glossary interaction v5 */\n $$('[data-example]').forEach(b=>b.addEventListener('click',()=>{reset(false);input.value=b.dataset.example;filter();scroll($('#cg-grid'));const first=results()[0];if(first){first.el.open=true;first.el.querySelector('summary').focus({preventScroll:true});}}));\n root.classList.add('cg-enhanced');")
        js=js.replace("count.textContent=found.length+", "count.textContent=(state.route==='start'?'Start here · ':'')+found.length+")
        js=js.replace("state.route?routeNames[state.route]+': a starting selection. Clear this view to browse the whole glossary.':''", "state.route==='start'?'Open a card for a clear explanation and one useful next step.':state.route?routeNames[state.route]+'. Browse all terms to explore the full guide.':''")
    css_path.write_text(css_path.read_text().split('/* Refined glossary v5 */')[0]+REFINED_CSS)
    js=js.replace("state.letter=b.dataset.letter;state.limit=12;", "state.letter=b.dataset.letter;state.route='';state.limit=12;")
    js=js.replace("state.saved=!state.saved;state.limit=12;", "state.saved=!state.saved;state.route='';state.topic='All';state.letter='';state.limit=12;")
    js_path.write_text(js)

